"""Registrar leituras e inspeção visual do lote B5-01 (registro 128)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==17
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,18))-{13},same
notes={1:'Abertura e quadro dos campos do Pacto.',2:'As sete ideias, Pacifismo, Liberação, Energia alternada e Magnetismo.',3:'Fragmentação, Despertar, Reserva vital e teste antes de aprovar.',4:'Abertura do Pacifismo e quadro de consulta rápida.',5:'Quem conta como pessoa e quadro do impedimento.',6:'Cumprimento, benefício e quadro do Fio de Corte.',7:'Quadro da Condução pela matéria, na mesa e suspensão.',8:'Prazo, calendário, encerramento e antes de usar.',9:'Abertura da Liberação e quadro de consulta rápida.',10:'Começo da sequência e Refluxo.',11:'Manutenção, mudanças de máximo e fora de combate.',12:'Descanso, encerramento e quadro de registro.',13:'Abertura da Promessa com a ressalva sobre Akira e quadro do acordo.',14:'Fim do quadro e quadro de decisões.',15:'Exceção, consequência de quebra.',16:'O que encerra o bloqueio.',17:'Três desfechos, registro e adaptação.'}
save('revisao-final.json',{'registro':128,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fontes e das regras citadas, quatro cópias, remissões e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; pente fino.'}],'ajuste_de_diagramacao':'Rótulo de cada caso preso ao título; sem outro ajuste necessário.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if i==13 else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Sem espaço grande conhecido; reavaliar o conjunto na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s047':[1,3],'s048':[4,8],'s049':[9,13],'s050':[13,17]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':128,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':128,'lote':'B5-01','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':51,'casos_pendentes':8,'lotes_pendentes':2,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B5-02','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':4},ensure_ascii=False))
